effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
vec4 u_xlat0;
vec4 u_xlat1;
vec2 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
void main()
{
    if(int(_direction) == 0) {
        u_xlat0.x = _cur_time * _speed + acScreenNorm.x;
        u_xlat0.x = fract(u_xlat0.x);
        u_xlat0.x = u_xlat0.x + (-acScreenNorm.x);
        u_xlat0.x = _amount * u_xlat0.x + acScreenNorm.x;
        u_xlat0.x = fract(u_xlat0.x);
        u_xlat0.y = fract(acScreenNorm.y);
        u_xlat0 = texture(inputImg, u_xlat0.xy);
    } else {
        u_xlat1.x = _cur_time * _speed + acScreenNorm.y;
        u_xlat1.x = fract(u_xlat1.x);
        u_xlat1.x = u_xlat1.x + (-acScreenNorm.y);
        u_xlat1.x = _amount * u_xlat1.x + acScreenNorm.y;
        u_xlat2.x = fract(acScreenNorm.x);
        u_xlat2.y = fract(u_xlat1.x);
        u_xlat0 = texture(inputImg, u_xlat2.xy);
    }
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
